let R0 = 7, R1 = 7;
let Z = 0;
function cmp(a, b) { Z = (a - b === 0) ? 1 : 0; } // CMP discards the value, sets Z
cmp(R0, R1);
// JNE = jump if Z == 0 (not equal); fall through if Z == 1 (equal)
if (Z === 0) {
  console.log('jump taken -> else block ran');
} else {
  console.log('fall through -> if-true block ran');
}
